"""Replay existing declarations using preserved compiler bytes and sealed sources."""
import datetime,hashlib,io,json,subprocess,tarfile,time
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
compiler=json.loads((P/'typescript-selected-closure-preservation-v1.json').read_text());archive=ROOT/compiler['archive'];assert hashlib.sha256(archive.read_bytes()).hexdigest()==compiler['archive_sha256']
cut=json.loads((P/'recovery-delta-receipt-v3.json').read_text());manifest_path=ROOT/cut['input_manifest']['path'];assert hashlib.sha256(manifest_path.read_bytes()).hexdigest()==cut['input_manifest']['sha256'];expected=json.loads(manifest_path.read_text())['effective_expected_files'];delta=ROOT/cut['delta_archive']['path'];assert hashlib.sha256(delta.read_bytes()).hexdigest()==cut['delta_archive']['sha256']
oracle=json.loads((P/'javascript-queue-type-consumer-oracle-v1.json').read_text());source_names=['agent/research/continuation-20261120/'+row['path']for row in oracle['declaration_and_manifest_sources']];subset=P/'typescript-sealed-declaration-subset-v1.tar.gz';source_entries=[]
with tarfile.open(delta,'r:gz')as original,tarfile.open(subset,'w:gz')as target:
 for name in source_names:
  member=original.getmember(name);assert member.isfile();body=original.extractfile(member).read();assert hashlib.sha256(body).hexdigest()==expected[name]['sha256'];info=tarfile.TarInfo(name);info.size=len(body);info.mode=0o600;info.mtime=0;target.addfile(info,io.BytesIO(body));source_entries.append({'path':name,'sha256':expected[name]['sha256'],'bytes':len(body)})
remote='/tmp/el-preserved-typescript-consumption-20261120-v1';tsroot=remote+'/node_modules/typescript';sources=remote+'/sealed-sources'
def run(args,**kwargs):
 result=subprocess.run(['docker','exec',*args],capture_output=True,timeout=90,**kwargs)
 assert result.returncode==0,result.stderr.decode()
 return result
start=time.monotonic();run(['engineering-library-frontend-1','mkdir',remote]);run(['engineering-library-frontend-1','mkdir','-p',tsroot,sources]);run(['engineering-library-frontend-1','tar','--no-same-owner','-xzf','/sources/engineering-library/'+compiler['archive'],'-C',tsroot]);run(['engineering-library-frontend-1','tar','--no-same-owner','-xzf','/sources/engineering-library/'+str(subset.relative_to(ROOT)),'-C',sources])
check="const fs=require('node:fs'),crypto=require('node:crypto');const p=require.resolve('typescript');console.log(JSON.stringify({path:p,sha256:crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'),version:require('typescript').version,node:process.version}));"
preflight=json.loads(run(['-e','NODE_PATH='+remote+'/node_modules','-w',remote,'engineering-library-frontend-1','node','-e',check]).stdout);assert preflight['path']==tsroot+'/lib/typescript.js';assert preflight['sha256']==next(row['sha256']for row in compiler['installed_source']['files']if row['path']=='lib/typescript.js')
files=[{'path':sources+'/'+entry['path'],'sha256':entry['sha256']}for entry in source_entries];result=run(['-i','-e','NODE_PATH='+remote+'/node_modules','-w',remote,'engineering-library-frontend-1','node','/sources/engineering-library/agent/research/continuation-20261120/check_javascript_queue_types_v1.cjs'],input=json.dumps({'oracle':oracle,'files':files}).encode());(P/'preserved-typescript-consumption-v1.stdout').write_bytes(result.stdout);(P/'preserved-typescript-consumption-v1.stderr').write_bytes(result.stderr);observed=json.loads(result.stdout);assert observed['correct']==observed['n']==16
old=json.loads((P/'javascript-queue-type-consumers-v1.json').read_text());assert all(path.startswith(tsroot+'/lib/')for path in observed['standard_library_files']);old_libs={Path(path).name:value['sha256']for path,value in old['standard_library_files'].items()};new_libs={Path(path).name:value['sha256']for path,value in observed['standard_library_files'].items()};assert new_libs==old_libs
record={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'VERIFIED_PRESERVED_COMPILER_AND_SEALED_DECLARATION_CONSUMPTION','wall_seconds':time.monotonic()-start,'compiler_preflight':preflight,'compiler_archive_sha256':compiler['archive_sha256'],'sealed_source_manifest_sha256':cut['input_manifest']['sha256'],'declaration_subset':{'path':str(subset.relative_to(ROOT)),'sha256':hashlib.sha256(subset.read_bytes()).hexdigest(),'members':source_entries},'observation':observed,'existing_cases_repeated':16,'new_distinct_cases':0,'same_57_standard_library_hashes':True,'compiler_loaded_from_owned_extracted_archive':True,'installed_compiler_used_for_replay':False,'borrowed_runtime':'ExistingLinuxARM64Node24.22.0; runtimebinarynotarchivedorinstalled','package_manager_or_environment_install':False,'application_source_execution':False,'new_infrastructure':False,'cold_boot_or_remote_recovery':False,'model_calls':0,'training_steps':0,'owned_temporary_root':remote}
with(P/'preserved-typescript-consumption-v1.json').open('x')as f:f.write(json.dumps(record,indent=2)+'\n')
print({'cases':16,'all_pass':True,'compiler_from_archive':True,'same_standard_library_hashes':True,'new_distinct_cases':0})
